-- 0002_taglines.sql
-- Supabase Schema Teardown. Generated by tools/build_sql.py; edit there, not here.

create table public.taglines (
  captured       timestamptz primary key,
  captured_label text not null,
  copy           text not null,
  note           text,
  state          text not null default 'normal' check (state in ('normal', 'hot', 'dead')),
  archive_url    text
);
alter table public.taglines enable row level security;
create policy "Public read" on public.taglines for select to anon, authenticated using (true);

